package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.WebauthnRpIdVO;

class WebauthnRpIdValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of webauthn rp id of tenant config")
  void test_webauthn_rp_id_value_holder_assign_plain_value() {
    Object holder = new Object();
    WebauthnRpIdValueHolder<Object> value = new WebauthnRpIdValueHolder<>(holder);
    Assertions.assertSame(holder, value.webauthnRpId("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnRpIdValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getWebauthnRpId().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.webauthnRpIdNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnRpIdValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getWebauthnRpId().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of webauthn rp id of tenant config")
  void test_webauthn_rp_id_value_holder_assign_value_object() {
    Object holder = new Object();
    WebauthnRpIdValueHolder<Object> value = new WebauthnRpIdValueHolder<>(holder);
    WebauthnRpIdVO vo = WebauthnRpIdVO.from("one");
    Assertions.assertFalse(value.getWebauthnRpIdValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.webauthnRpId(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWebauthnRpIdValue().orElseThrow());
    Assertions.assertSame(holder, value.webauthnRpId(Optional.empty()));
    Assertions.assertFalse(value.getWebauthnRpIdValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.webauthnRpId(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWebauthnRpIdValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of webauthn rp id of tenant config against the original")
  void test_webauthn_rp_id_value_holder_read() {
    Object holder = new Object();
    WebauthnRpIdValueHolder<Object> value = new WebauthnRpIdValueHolder<>(holder);
    WebauthnRpIdVO vo = WebauthnRpIdVO.from("one");
    WebauthnRpIdVO other = WebauthnRpIdVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getWebauthnRpIdValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWebauthnRpId(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWebauthnRpId(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.webauthnRpId(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWebauthnRpId(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWebauthnRpId(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of webauthn rp id of tenant config")
  void test_webauthn_rp_id_value_holder_unset() {
    Object holder = new Object();
    WebauthnRpIdValueHolder<Object> value = new WebauthnRpIdValueHolder<>(holder);
    WebauthnRpIdVO vo = WebauthnRpIdVO.from("one");
    value.webauthnRpId(vo);
    Assertions.assertSame(holder, value.unsetWebauthnRpIdIfMatches("webauthnRpId_other"));
    Assertions.assertTrue(value.getWebauthnRpIdValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWebauthnRpIdIfMatches("webauthnRpId"));
    Assertions.assertFalse(value.getWebauthnRpIdValue().isPresent(),
        "The field name must clear the value");
    value.webauthnRpId(vo);
    Assertions.assertSame(holder, value.unsetWebauthnRpId());
    Assertions.assertFalse(value.getWebauthnRpIdValue().isPresent(), "Unset must clear the value");
  }
}
